() => {
  const inputs = document.querySelectorAll('input');
  const result = [];
  inputs.forEach((inp, i) => {
    result.push({ index: i, type: inp.type, placeholder: inp.placeholder, id: inp.id, name: inp.name });
  });
  return result;
}

() => {
  const setValue = (el, value) => {
    const proto = el.constructor.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
    setter.call(el, value);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };
  const inputs = document.querySelectorAll('input');
  setValue(inputs[0], 'admin');
  setValue(inputs[1], 'admin123');
  return { user: inputs[0].value, pass: inputs[1].value };
}

