() => {
  const selects = document.querySelectorAll('select');
  for (const sel of selects) {
    const opts = Array.from(sel.options).map(o => o.textContent);
    if (opts.some(t => t.includes('数据资源'))) {
      const target = Array.from(sel.options).find(o => o.textContent.includes('数据资源'));
      const setter = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set;
      setter.call(sel, target.value);
      sel.dispatchEvent(new Event('change', { bubbles: true }));
      return { selected: target.textContent, value: target.value };
    }
  }
  return { found: false, selects: selects.length };
}

() => {
  const selects = document.querySelectorAll('select');
