    index: i,
    value: sel.value,
    selectedText: sel.options[sel.selectedIndex]?.textContent,
    optionCount: sel.options.length,
    options: Array.from(sel.options).map(o => o.textContent).slice(0, 8),
    parentClass: sel.parentElement?.className?.slice?.(0, 60) || ''
  }));
}

