() => {
  // Find the knowledge item titled 高频指标口径速查 and click its 查看详情 button
  const all = document.querySelectorAll('*');
  // Strategy: find buttons with 查看详情, then check nearby title text
  const detailBtns = Array.from(document.querySelectorAll('button')).filter(b => b.textContent.trim().includes('查看详情'));
  for (const btn of detailBtns) {
    // Walk up to a container that includes the title
    let container = btn;
    for (let i = 0; i < 6 && container; i++) {
      container = container.parentElement;
      if (container && container.textContent.includes('高频指标口径速查')) {
        btn.click();
        return { clicked: true, title: '高频指标口径速查' };
      }
    }
  }
  return { clicked: false, count: detailBtns.length };
}

