() => {
  // Find the title node with exact text, then locate the nearest item container's 查看详情 button
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let titleEl = null;
  while (walker.nextNode()) {
    const n = walker.currentNode;
    if (n.nodeValue && n.nodeValue.trim() === '高频指标口径速查') { titleEl = n.parentElement; break; }
  }
  if (!titleEl) return { found: false };
  // Walk up to find a container that also contains a 查看详情 button but is not the whole list
  let container = titleEl;
  for (let i = 0; i < 10 && container; i++) {
    const btns = container.querySelectorAll ? Array.from(container.querySelectorAll('button')) : [];
    const detailBtn = btns.find(b => (b.getAttribute('aria-label') || b.getAttribute('title') || '') === '查看详情');
    const hasOtherTitles = ['两期对比口径', '组织机构', '维度枚举值'].some(t => container.textContent.includes(t));
    if (detailBtn && !hasOtherTitles) {
      detailBtn.click();
      return { clicked: true };
    }
    container = container.parentElement;
  }
  return { clicked: false };
}

() => {
  // Inspect the expanded detail area: find text with 片段 and nearby heading
  const bodyText = document.body.innerText;
  const idx = bodyText.indexOf('个检索片段');
  const snippet = idx >= 0 ? bodyText.slice(Math.max(0, idx - 80), idx + 120) : '';
  return { snippet };
}

() => {
  const bodyText = document.body.innerText;
  const start = bodyText.indexOf('高频指标口径速查\n3 个检索片段');
  if (start < 0) return { found: false };
  return { detail: bodyText.slice(start, start + 1500) };
}

() => {
  const bodyText = document.body.innerText;
  // Count knowledge items by counting 查看详情 buttons in the list
  const detailBtns = Array.from(document.querySelectorAll('button')).filter(b => (b.getAttribute('aria-label') || b.getAttribute('title') || '') === '查看详情');
  // Get the count badge
  const m = bodyText.match(/已登记知识（(\d+)\s*条）/);
  // Get all knowledge titles from the list (they appear with "N 个片段 · admin · date")
  const titleMatches = bodyText.match(/[^\n]+\n\d+ 个片段 · admin · 2026-\d{2}-\d{2}/g) || [];
  const titles = titleMatches.map(t => t.split('\n')[0]);
  return {
    badgeCount: m ? m[1] : null,
    detailButtonCount: detailBtns.length,
    titles
  };
}
